330	     *  voided claim, a claim in a closed period, the claim's own person, or a person retired on its date. */
331	    @Transactional
332	    public Claim reassign(String sheetId, String user, long claimId, long toPersonId) {
333	        Claim claim = claims.findForUpdateByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
334	        refuseClosed(sheetId, claim.getDate());
335	        if (!roles.allows(sheetId, user, "reassign")) {
336	            throw new ClaimReassignException("Your role may not reassign a claim.");
337	        }
338	        if (!claim.getStatus().canMove()) {
339	            throw new ClaimReassignException("A " + claim.getStatus() + " claim cannot be reassigned.");
340	        }
341	        Person from = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
342	                .orElseThrow(PersonNotFoundException::new);
343	        Person to = people.findByIdAndSheetId(toPersonId, sheetId).orElseThrow(PersonNotFoundException::new);
344	        if (from.getId().equals(to.getId())) {
345	            throw new ClaimReassignException("The claim is already " + to.getName() + "'s.");
346	        }
347	        refuseRetired(to, claim.getDate());
348	        Rollup.Snapshot before = rollup.take(sheetId);
349	        claim.setPersonId(to.getId());
350	        claim.setStated(false, null);
351	        claim.setListOrder(claims.maxListOrder(sheetId) + 1);
352	        Claim updated = claims.saveAndFlush(claim);
353	        audit("CLAIM_REASSIGNED", updated, to, user, updated.getNumber(),
354	                " from=" + from.getName() + " to=" + to.getName());
355	        rollup.recordChanges(sheetId, user, before);
356	        return updated;
357	    }
358	
359	    /** What a split did: the claim it kept, with the rest of its amount, and the claim it split off. */
360	    public record Split(Claim kept, Claim split) {
361	    }
362	
363	    /** Split an amount off an OPEN claim: the claim keeps the rest of its amount and loses any figure a
364	     *  statement bound it to; a new OPEN claim of the person with the amount split off, the same date and
365	     *  note, the next number, opened by the user and due by its date plus the terms in force on it, is
366	     *  listed as the sheet's newest, naming the original's number as split from. Refused unless the user's
367	     *  role may open a claim, the claim is OPEN and not deferred, and the amount is above 0.00 and below the
368	     *  claim's; and for a claim in a closed period. */
369	    @Transactional
370	    public Split split(String sheetId, String user, long claimId, BigDecimal amount) {
371	        Claim claim = claims.findForUpdateByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
372	        refuseClosed(sheetId, claim.getDate());
373	        roles.require(sheetId, user, "open");
374	        if (claim.getStatus() != ClaimStatus.OPEN) {
375	            throw new ClaimSplitException("Only an OPEN claim can be split.");
376	        }
377	        LocalDate today = sheets.today(sheetId);
378	        if (claim.deferredOn(today)) {
379	            throw new ClaimSplitException("The claim is deferred until " + claim.getDeferredUntil() + ".");
380	        }
381	        BigDecimal part = amount.setScale(2);
382	        if (part.signum() <= 0 || part.compareTo(claim.getAmount()) >= 0) {
383	            throw new ClaimSplitException("Split off more than 0.00 and less than the claim's amount.");
384	        }
385	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
386	                .orElseThrow(PersonNotFoundException::new);
387	        Rollup.Snapshot before = rollup.take(sheetId);
388	        claim.setAmount(claim.getAmount().subtract(part));
389	        claim.setStated(false, null);
390	        Claim kept = claims.saveAndFlush(claim);
391	        int terms = person.getTerms() != null ? person.getTerms()
392	                : sheetRows.findById(sheetId).orElseThrow(SheetNotFoundException::new)
393	                        .termsFor(person.gradeOn(claim.getDate()), claim.getDate());
394	        Claim split = new Claim(sheetId, person.getId(), part, claim.getDate(), claim.getDate().plusDays(terms),
395	                claim.getNote(), null);
396	        split.setListOrder(claims.maxListOrder(sheetId) + 1);
397	        split.setStatus(ClaimStatus.OPEN);
398	        split.setNumber(sheets.nextClaimNumber(sheetId, claim.getDate()));
399	        split.setOpenedBy(user);
400	        split.setSplitFrom(claim.getNumber());
401	        logStatus(split, person, user);
402	        split = claims.saveAndFlush(split);
403	        audit("CLAIM_SPLIT", kept, person, user, kept.getNumber(), " into=" + split.getNumber());
404	        audit("CLAIM_OPENED", split, person, user);
405	        rollup.recordChanges(sheetId, user, before);
406	        return new Split(kept, split);
407	    }
408	
409	    /** What a bulk open did: how many it opened and refused, and the claims it opened. */
410	    public record BulkOpened(int opened, int refused, List<Claim> claims) {
411	    }
412	
413	    /** Open the chosen claims together, numbering them in list order (people in the order they were added,
414	     *  each person's claims newest first); a claim that cannot be opened is left as it is and counted as
415	     *  refused, as is one not on the sheet. */
416	    @Transactional
417	    public BulkOpened bulkOpen(String sheetId, String user, Collection<Long> claimIds) {
418	        Set<Long> chosen = new HashSet<>(claimIds);
419	        if (roles.isViewer(sheetId, user) || sheets.isArchived(sheetId)) {
420	            return new BulkOpened(0, chosen.size(), List.of());
421	        }
422	        List<Claim> opened = new ArrayList<>();
423	        for (Claim claim : inListOrder(sheetId, chosen)) {
424	            try {
425	                opened.add(changeStatus(sheetId, user, claim.getId(), ClaimStatus.OPEN));
426	            } catch (ClaimStatusException | PeriodClosedException | ClaimNotFoundException
427	                    | ActionNotAllowedException e) {
428	                // refused: left as it is
429	            }
430	        }
431	        return new BulkOpened(opened.size(), chosen.size() - opened.size(), opened);
432	    }
433	
434	    /** What a bulk settle did: how many it settled (PENDING included) and refused, and the claims it changed. */
435	    public record BulkSettled(int settled, int refused, List<Claim> claims) {
436	    }
437	
438	    /** Settle the chosen claims together in list order (people in the order they were added, each person's
439	     *  claims newest first), each as a single settle by the user would: one a clerk puts PENDING counts as
440	     *  settled, and one that cannot be settled is left as it is and counted as refused, as is one not on
441	     *  the sheet. */
442	    @Transactional
443	    public BulkSettled bulkSettle(String sheetId, String user, Collection<Long> claimIds) {
444	        Set<Long> chosen = new HashSet<>(claimIds);
445	        if (roles.isViewer(sheetId, user) || sheets.isArchived(sheetId)) {
446	            return new BulkSettled(0, chosen.size(), List.of());
447	        }
448	        List<Claim> settled = new ArrayList<>();
449	        for (Claim claim : inListOrder(sheetId, chosen)) {
450	            try {
451	                settled.add(changeStatus(sheetId, user, claim.getId(), ClaimStatus.SETTLED));
452	            } catch (ClaimStatusException | ClaimSettlerException | ClaimDeferException | ClaimProofException
453	                    | PeriodClosedException | ActionNotAllowedException
454	                    | ClaimNotFoundException e) {
455	                // refused: left as it is
456	            }
457	        }
458	        return new BulkSettled(settled.size(), chosen.size() - settled.size(), settled);
459	    }
460	
461	    /** The sheet's chosen claims in list order: people in the order they were added, each person's claims
462	     *  newest first. */
463	    private List<Claim> inListOrder(String sheetId, Set<Long> chosen) {
464	        Map<Long, Integer> personOrder = new HashMap<>();
465	        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
466	            personOrder.put(person.getId(), personOrder.size());
467	        }
468	        return claims.findBySheetIdOrderByListOrderDesc(sheetId).stream()
469	                .filter(c -> chosen.contains(c.getId()))
470	                .sorted(Comparator.comparing((Claim c) -> personOrder.getOrDefault(c.getPersonId(), Integer.MAX_VALUE)))
471	                .toList();
472	    }
473	
474	    /** A person, their statements in the order taken, and their claims newest first. */
475	    public record Stated(Person person, List<Statement> statements, List<Claim> claims) {
476	    }
477	
478	    /** Take a person's statement: record their due-total now (late charges included) and how many claims
479	     *  count, and bind each claim that counts to its rate figure now, under its late charge and floor (the charge is
480	     *  never bound: it keeps following the sheet's today, and the floor is applied on top; a PENDING claim is bound only once it is back to
481	     *  OPEN); a claim that does not count, is OPEN or PENDING and dated within one of its person's holds, or is
482	     *  deferred past the sheet's today, is left unbound. */
483	    @Transactional
484	    public Stated statement(String sheetId, String user, long personId) {
485	        Person person = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
486	        LocalDate today = sheets.today(sheetId);
487	        List<Claim> theirs = claims.findForUpdateBySheetIdAndPersonIdOrderByListOrderDesc(sheetId, personId);
488	        Rollup.Snapshot before = rollup.take(sheetId);
489	        BigDecimal total = BigDecimal.ZERO.setScale(2);
490	        boolean figure = false;
491	        int counted = 0;
492	        for (Claim claim : theirs) {
493	            if (!claim.getStatus().counts() || (claim.getStatus().isOpen() && person.heldOn(claim.getDate()))
494	                    || claim.deferredOn(today)) {
495	                claim.setStated(false, null);
496	                continue;
497	            }
498	            BigDecimal due = due(claim, person);
499	            if (due != null) {
500	                total = total.add(charged(claim, due));
501	                figure = true;
502	            }
503	            claim.setStated(true, due);
504	            counted++;
505	        }
506	        boolean rated = rates.findInForce(sheetId, person.gradeOn(today), today).isPresent();
507	        BigDecimal summed = total;
508	        BigDecimal dueTotal = rated || figure
509	                ? sheetRows.findById(sheetId).map(s -> s.capped(summed)).orElse(summed) : null;
510	        claims.saveAllAndFlush(theirs);
511	        statements.saveAndFlush(new Statement(sheetId, personId, today, dueTotal, counted));
512	        audit.recordOnCommit("STATEMENT sheet=" + sheetId + " by=" + user + " name=" + person.getName()
513	                + " due-total=" + (dueTotal == null ? "n/a" : dueTotal.toPlainString()) + " claims=" + counted);
514	        rollup.recordChanges(sheetId, user, before);
515	        return new Stated(person, statements.findByPersonIdOrderByIdAsc(personId), theirs);
516	    }
517	
518	    /** Refuse a change to a claim dated inside a closed period. Locks the sheet first, so a period being
519	     *  closed at the same moment is seen. */
520	    private void refuseClosed(String sheetId, LocalDate date) {
521	        sheetRows.findForUpdateById(sheetId).orElseThrow(SheetNotFoundException::new);
522	        if (periods.closedOn(sheetId, date)) {
523	            throw new PeriodClosedException();
524	        }
525	    }
526	
527	    /** Refuse voiding a SETTLED claim unless the user is a steward and the sheet's today is within 7 days
528	     *  of the date its status log last records it SETTLED. */
529	    private void refuseVoidSettled(Claim claim, String sheetId, String user) {
530	        if (!roles.isSteward(sheetId, user)) {
531	            throw new ClaimVoidException("Only a steward can void a settled claim.");
532	        }
533	        LocalDate settledOn = claim.getStatusLog().stream()
534	                .filter(line -> line.getStatus() == ClaimStatus.SETTLED)
535	                .map(StatusChange::getOn)
536	                .reduce((first, last) -> last)
537	                .orElse(null);
538	        if (settledOn == null || sheets.today(sheetId).isAfter(settledOn.plusDays(7))) {
539	            throw new ClaimVoidException("A settled claim can only be voided within 7 days of settling it.");
540	        }
541	    }
542	
543	    /** Refuse settling or approving a claim with no proof whose due is above the proof threshold in force on
544	     *  its date; a due of n/a, or no threshold then, needs none. */
545	    private void refuseUnproved(Claim claim, BigDecimal due) {
546	        BigDecimal threshold = sheetRows.findById(claim.getSheetId()).orElseThrow(SheetNotFoundException::new)
547	                .proofThresholdOn(claim.getDate());
548	        if (threshold != null && due != null && due.compareTo(threshold) > 0 && claim.getProofs() == 0) {
549	            throw new ClaimProofException("The claim's due is above the proof threshold: add a proof first.");
550	        }
551	    }
552	
553	    /** Whether a clerk is settling a due above the sheet's clerk limit; a steward settles anything, and a
554	     *  due of n/a, or a sheet with no limit, is within it. */
555	    private boolean overLimit(String sheetId, String user, BigDecimal due) {
556	        BigDecimal limit = sheetRows.findById(sheetId).orElseThrow(SheetNotFoundException::new).getClerkLimit();
557	        return limit != null && due != null && due.compareTo(limit) > 0 && !roles.isSteward(sheetId, user);
558	    }
559	
560	    /** Refuse a negative amount that does not name a SETTLED claim of the person by number, and a claim of
561	     *  0.00 or more that names one. */
562	    private void refuseCorrection(String sheetId, long personId, BigDecimal amount, String corrects) {
563	        if (amount.signum() >= 0) {
564	            if (corrects != null) {
565	                throw new ClaimCorrectionException("Only a negative amount corrects a claim.");
566	            }
567	            return;
568	        }
569	        if (corrects == null) {
570	            throw new ClaimCorrectionException(
571	                    "A negative amount is a correction: name the number of the settled claim it corrects.");
572	        }
573	        if (!claims.existsBySheetIdAndPersonIdAndNumberAndStatus(sheetId, personId, corrects, ClaimStatus.SETTLED)) {
574	            throw new ClaimCorrectionException("A correction must name a settled claim of the same person.");
575	        }
576	    }
577	
578	    /** Refuse a claim dated after its person's retirement date. */
579	    private static void refuseRetired(Person person, LocalDate date) {
580	        if (person.retiredOn(date)) {
581	            throw new PersonRetiredException();
582	        }
583	    }
584	
585	    /** A claim's figure: the due fixed when settled, else the one its last statement bound (not while
586	     *  PENDING), else its live due; none when that is n/a. */
587	    private BigDecimal due(Claim claim, Person person) {
588	        if (claim.getSettledDue() != null) {
589	            return claim.getSettledDue();
590	        }
591	        return claim.isBound() ? claim.getStatedDue() : liveDue(claim, person);
592	    }
593	
594	    /** Log the status a claim has just taken: by the user, on the sheet's today, with its due as the
595	     *  screen shows it now. */
596	    private void logStatus(Claim claim, Person person, String user) {
597	        claim.logStatus(user, sheets.today(claim.getSheetId()), shownDue(claim, person));
598	    }
599	
600	    /** A claim's due as the screen shows it: fixed when settled, else its figure (bound or live) with its
601	     *  late charge on top; none when that is n/a. */
602	    private BigDecimal shownDue(Claim claim, Person person) {
603	        if (claim.getSettledDue() != null) {
604	            return claim.getSettledDue();
605	        }
606	        BigDecimal figure = due(claim, person);
607	        return figure == null ? null : charged(claim, figure);
608	    }
609	
610	    /** A claim's due from its figure: its late charge on the sheet's today on top while it is OPEN or
611	     *  PENDING, then at least the floor in force on its date (a correction has neither). */
612	    private BigDecimal charged(Claim claim, BigDecimal figure) {
613	        return Rollup.charged(sheetRows.findById(claim.getSheetId()), claim, figure);
614	    }
615	
616	    /** The claim's rate figure: its amount at the rate in force on its date of its person's grade in force
617	     *  then, before any late charge or floor; none when no rate applies. */
618	    private BigDecimal liveDue(Claim claim, Person person) {
619	        Sheet sheet = sheetRows.findById(claim.getSheetId()).orElseThrow(SheetNotFoundException::new);
620	        RoundingMode rounding = sheet.rounding(roundingDate(claim));
621	        return rates.findInForce(claim.getSheetId(), person.gradeOn(claim.getDate()), claim.getDate())
622	                .map(rate -> due(claim.getAmount(), rate, rounding))
623	                .orElse(null);
624	    }
625	
626	    /** The date a claim's figures round by: its own, or for a correction the date of the claim it corrects. */
627	    private LocalDate roundingDate(Claim claim) {
628	        if (!claim.isCorrection()) {
629	            return claim.getDate();
630	        }
631	        return claims.findBySheetIdAndPersonIdAndNumber(claim.getSheetId(), claim.getPersonId(), claim.getCorrects())
632	                .map(Claim::getDate).orElse(claim.getDate());
633	    }
634	
635	    /** An amount times a rate, divided by 100, rounded to cents. */
636	    private static BigDecimal due(BigDecimal amount, Rate rate, RoundingMode rounding) {
637	        return amount.multiply(rate.getRate()).movePointLeft(2).setScale(2, rounding);
638	    }
639	
640	    /** The due a settled claim was fixed at, as its audit line ends: n/a when it has none. */
641	    private static String dueField(Claim claim) {
642	        return " due=" + (claim.getSettledDue() == null ? "n/a" : claim.getSettledDue().toPlainString());
643	    }
644	
645	    /** A due as an audit line shows it: n/a when there is none. */
646	    private static String show(BigDecimal due) {
647	        return due == null ? "n/a" : due.toPlainString();
648	    }
649	
650	    /** Tell each user watching the claim's person, in the order they started watching. */
651	    private void notifyWatchers(Claim claim, Person person, String user) {
652	        for (Watch watch : watches.findByPersonIdOrderByIdAsc(person.getId())) {
653	            audit.recordOnCommit("NOTIFY sheet=" + claim.getSheetId() + " by=" + user + " user=" + watch.getUser()
654	                    + " person=" + person.getName() + " number=" + claim.getNumber());
655	        }
656	    }
657	
658	    /** The amount as the screen shows it (two decimals), the date YYYY-MM-DD. */
659	    private void audit(String event, Claim claim, Person person, String user) {
660	        audit(event, claim, person, user, claim.getNumber(), "");
661	    }
662	
663	    /** A claim with a number (a voided claim keeps its own) follows its date with number=, then any extra fields. */
664	    private void audit(String event, Claim claim, Person person, String user, String number, String extra) {
665	        audit.recordOnCommit(event + " sheet=" + claim.getSheetId() + " by=" + user
666	                + " person=" + person.getName() + " amount=" + claim.getAmount().toPlainString()
667	                + " date=" + claim.getDate() + (number != null ? " number=" + number : "") + extra);
668	    }
669	}
